<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import {useEmotional} from '../composables/useEmotional.js';
import {paginateEmotionalScene,boundaryLabel,emotionalProposalSummary,typographicQuotes,emotionalEnvelopeTruth} from '../lib/emotional-presentation.js';
import {emotionalIntakeText} from '../../../../packages/engine/src/emotional-copy.js';
import EmotionalIllustration from './EmotionalIllustration.vue';
import CountdownBar from './CountdownBar.vue';
import WaxSeal from './WaxSeal.vue';
import EnvelopeText from './EnvelopeText.vue';
import '../emotional-fonts.css';
import '../emotional.css';

const props=defineProps<{prepared?:boolean}>();
const appPath=props.prepared?'/demo':'/preview';
const ui=useEmotional(!!props.prepared);
const {flow,loading,working,available,connected,error,recoveryHome,release,quotaLimited,notice,pending,pageIndex,pages,remaining,sealVerified,reveal,initialSeal,commitmentStored,sealMismatch,memories,memoryId}=ui;
const input=ref(''),editing=ref(false),presenting=ref(false),reviewing=ref(false),envelope=ref<HTMLDialogElement>(),history=ref<HTMLDialogElement>(),library=ref<HTMLDialogElement>(),people=ref<HTMLDialogElement>(),passage=ref<HTMLElement>(),measure=ref<HTMLElement>(),chatLog=ref<HTMLElement>();
const adventure=computed(()=>flow.value?.adventure),decision=computed(()=>adventure.value?.scene.decision),urgent=computed(()=>adventure.value?.phase==='deciding'||presenting.value),lastPage=computed(()=>pageIndex.value>=pages.value.length-1),seconds=computed(()=>Math.ceil(remaining.value/1000));
const art=(id:string)=>flow.value?`${ui.apiBase}/art/${flow.value.id}/${id}`:'';
const cast=computed(()=>adventure.value?.art.filter(a=>a.id!=='scene')??[]);
const canCreate=computed(()=>!memoryId&&!!flow.value&&['chat','proposal','finished','failed'].includes(flow.value.status));
const readingFinished=ref(false),finishedHome=computed(()=>flow.value?.status==='finished'&&!memoryId&&!readingFinished.value);
const question=ref<HTMLElement>(),revealCount=ref(0),copied=ref('');
const chapter=computed(()=>{const id=adventure.value?.scene.id??'';return id.startsWith('F')?4:/^(?:S3|D3|ARR)/u.test(id)?3:/^(?:S2|D2)/u.test(id)?2:1;});
const choiceHint=computed(()=>pageIndex.value===0&&adventure.value?.scene.id==='S2'&&adventure.value.scene.paragraphs.some(p=>p.includes('public display, private deposit, or keeping both.'))?'The final decision has two buttons. “Keeping both” is what happens if you let that final timer run out.':'');
const stage=computed(()=>/Illustrating/.test(flow.value?.progress?.label??'')?3:/Checking/.test(flow.value?.progress?.label??'')?2:/Writing/.test(flow.value?.progress?.label??'')?1:0);
const stages=[{title:'Creating the world',description:'A place, its people, and a mystery for your preferences.'},{title:'Writing the story',description:'The scenes and reactions are taking shape.'},{title:'Checking every path',description:'We’re checking the story before it can be sealed.'},{title:'Illustrating your adventure',description:'Preparing the setting and the faces you’ll meet.'}];
const suggestions=computed(()=>{if(editing.value||flow.value?.status!=='chat')return[];const last=flow.value.messages.at(-1);if(last?.kind!=='question')return[];const text=last.content;return /intensity|gentle|moderate|tension/iu.test(text)?['Gentle','Moderate','Tense']:/boundar|avoid|leave out|exclude/iu.test(text)?['None','I’d rather skip']:/stay with|shift|accompany|change/iu.test(text)?['Stay with this feeling','A change of atmosphere']:['Curious','A little low','Restless','I’d rather skip my mood'];});
const playerName=computed(()=>adventure.value?.playerName??'Your character');
const initials=(name:string)=>name.trim().split(/\s+/u).slice(0,2).map(part=>part[0]).join('').toUpperCase();
const animatedText=ref(true);try{animatedText.value=localStorage.getItem('sealed-envelope-animation')!=='off';}catch{/* Default animation still respects reduced motion. */}
watch(animatedText,value=>{try{localStorage.setItem('sealed-envelope-animation',value?'on':'off');}catch{/* Preference cannot be saved in this browser. */}});
const openedTruth=computed(()=>sealVerified.value===true?emotionalEnvelopeTruth(reveal.value?.canonical):null);
const explanationChoice=computed(()=>props.prepared?adventure.value?.decisions.find(item=>item.id==='D2')?.choice:undefined);
const explanationHeading=computed(()=>explanationChoice.value==='B'?'The explanation you archived unread':explanationChoice.value==='T'?'The explanation you left unread':'What was inside');
const shortHash=computed(()=>flow.value?.seal?flow.value.seal.slice(0,8)+'…'+flow.value.seal.slice(-8):'');
const fullHash=computed(()=>flow.value?.seal?.match(/.{1,4}/gu)?.join(' ')??'');
const chatMode=computed(()=>flow.value&&['chat','chatting','proposal'].includes(flow.value.status));
watch(()=>flow.value?.messages.length,async()=>{await nextTick();if(chatLog.value)chatLog.value.scrollTop=chatLog.value.scrollHeight;});
watch(()=>flow.value?.status,(next,prior)=>{editing.value=false;if(next==='finished'&&prior&&prior!=='finished')readingFinished.value=true;else if(next!=='finished')readingFinished.value=false;});
watch(()=>adventure.value?.scene.id,()=>{presenting.value=false;reviewing.value=false;});
watch(pageIndex,()=>{if(passage.value)passage.value.scrollTop=0;if(window.innerWidth<=760)window.scrollTo(0,0);});
watch(()=>urgent.value||reviewing.value,async active=>{if(active){await nextTick();window.scrollTo(0,0);question.value?.focus({preventScroll:true});}});
async function answer(value=input.value){if(!value.trim())return;input.value='';editing.value=false;await ui.answer(value);}
async function begin(){reviewing.value=false;presenting.value=true;await nextTick();await ui.act('begin');if(adventure.value?.phase!=='deciding'&&!pending.value){presenting.value=false;reviewing.value=true;}}
async function openEnvelope(){copied.value='';await ui.openEnvelope();revealCount.value++;envelope.value?.showModal();}
async function openLibrary(){await ui.loadMemories();library.value?.showModal();}
async function newAdventure(){library.value?.close();envelope.value?.close();input.value='';await ui.newAdventure();}
async function copyHash(){try{await navigator.clipboard.writeText(flow.value?.seal??'');copied.value='Copied the full hash.';}catch{copied.value='Select the full hash below to copy it.';}}
function shortcut(event:KeyboardEvent){if(event.repeat||event.ctrlKey||event.altKey||event.metaKey||document.querySelector('dialog[open]')||adventure.value?.phase!=='deciding'||working.value||pending.value||event.target instanceof HTMLInputElement||event.target instanceof HTMLTextAreaElement)return;const key=event.key.toUpperCase();if(key==='A'||key==='B'){event.preventDefault();void ui.act('choose',key);}}
function download(){if(!reveal.value)return;const link=document.createElement('a'),url=URL.createObjectURL(new Blob([reveal.value.canonical],{type:'application/json'}));link.href=url;link.download='sealed-'+flow.value!.id+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
declare global {interface Window {render_game_to_text?:()=>string}}
const textState=()=>JSON.stringify({mode:flow.value?.status??'welcome',title:adventure.value?.title??'SEALED',scene:adventure.value?.scene.id,page:pageIndex.value+1,pages:pages.value.length,finishedHome:finishedHome.value,reviewing:reviewing.value,envelope:envelope.value?.open?{detail:openedTruth.value,verified:sealVerified.value}:undefined,visibleText:finishedHome.value?undefined:urgent.value||reviewing.value?decision.value?.prompt:pages.value[pageIndex.value],decision:urgent.value||reviewing.value?{options:decision.value?.options,inaction:decision.value?.inaction,remainingSeconds:urgent.value?seconds.value:null}:null,chat:chatMode.value?flow.value?.messages.slice(-4).map(m=>({...m,content:m.role==='assistant'?emotionalIntakeText(m.kind,m.content):m.content})):undefined,error:error.value||flow.value?.error||null,sealVerified:sealVerified.value});
let observer:ResizeObserver|undefined,frame=0,alive=true;
function layoutReading(){
  const box=passage.value,probe=measure.value;if(!box||!probe||box.clientHeight<30||box.clientWidth<30)return;
  probe.style.width=box.clientWidth+'px';
  const height=window.innerWidth<=760?Math.max(240,window.innerHeight-360):box.clientHeight;
  const fits=(paragraphs:string[])=>{probe.replaceChildren(...paragraphs.map(text=>{const p=document.createElement('p');p.textContent=typographicQuotes(text);return p;}));return probe.scrollHeight<=height-2;};
  ui.layoutReading(paginateEmotionalScene(adventure.value?.scene.paragraphs??[],fits));probe.replaceChildren();
}
function scheduleLayout(){if(!alive)return;cancelAnimationFrame(frame);frame=requestAnimationFrame(layoutReading);}
watch(passage,element=>{observer?.disconnect();if(element)observer?.observe(element);scheduleLayout();},{flush:'post'});
watch(()=>JSON.stringify([flow.value?.id,adventure.value?.scene.id,adventure.value?.scene.paragraphs]),scheduleLayout,{flush:'post'});
onMounted(()=>{document.documentElement.lang='en';document.body.classList.add('sealed-preview');document.title='SEALED — A story for your moment';window.render_game_to_text=textState;if(typeof ResizeObserver!=='undefined'){observer=new ResizeObserver(scheduleLayout);if(passage.value)observer.observe(passage.value);}window.addEventListener('resize',scheduleLayout);window.addEventListener('keydown',shortcut);document.fonts?.addEventListener('loadingdone',scheduleLayout);void document.fonts?.ready.then(scheduleLayout);scheduleLayout();});
onUnmounted(()=>{alive=false;document.body.classList.remove('sealed-preview');observer?.disconnect();cancelAnimationFrame(frame);window.removeEventListener('resize',scheduleLayout);window.removeEventListener('keydown',shortcut);document.fonts?.removeEventListener('loadingdone',scheduleLayout);if(window.render_game_to_text===textState)delete window.render_game_to_text;});
</script>

<template>
  <div class="e-app" :class="{'e-urgent':urgent,'e-reviewing':reviewing,'e-prepared':props.prepared}">
    <header class="e-header"><a class="e-brand" :href="appPath">SEALED<span class="e-brand-dot">.</span><small v-if="props.prepared" class="e-demo-label">Pre-generated Meta demo</small></a><span v-if="!props.prepared" class="e-header-note">A story for this moment</span><WaxSeal v-if="adventure" :state="flow?.status==='finished'?'cracked':'sealed'" :size="26" class="e-header-seal"/><div class="e-header-actions"><button v-if="canCreate" class="e-link" :disabled="working||!!pending||!available" @click="newAdventure">{{props.prepared?'Replay this demo':'New adventure'}}</button><button class="e-link" :disabled="urgent" @click="openLibrary">{{props.prepared?'Your demo runs':'Your stories'}}</button></div></header>
    <div v-if="error||!connected||sealMismatch" class="e-alert" role="alert"><span>{{sealMismatch?'The seal differs from the commitment saved before play.':error||'Connection interrupted. Your choices are saved; an open decision keeps its deadline.'}}<template v-if="flow"> Reference: {{flow.id.slice(0,8)}}.</template></span><button class="e-link" :disabled="working" @click="quotaLimited?ui.dismissError():ui.retry()">{{quotaLimited?'Dismiss':pending?'Recover last action':'Reconnect'}}</button></div>
    <main v-if="loading" class="e-wait" aria-live="polite"><span class="e-orbit" aria-hidden="true"></span>Finding your place…</main>
    <main v-else-if="!flow" class="e-welcome">
      <div class="e-cover-art" aria-hidden="true"><div class="e-paper e-paper-back"></div><div class="e-paper"><span class="e-paper-mark">SEALED</span><WaxSeal :size="68"/></div><span class="e-cover-annotation">Some stories arrive<br/>at the right moment.</span></div>
      <section v-if="props.prepared" class="e-intro"><p class="e-kicker">A reviewed Meta adventure</p><h1>A moment worth<br/>noticing.</h1><p class="e-lead">Play The Shelter Sheet, a complete story generated earlier with Meta and reviewed before this demo. Your choices decide what happens.</p><p class="e-format">Read at your pace. Three timed decisions. One sealed envelope.</p><button class="e-primary" :disabled="working||!!pending||!available" @click="ui.newAdventure">Play the reviewed demo <span aria-hidden="true">↗</span></button><p class="e-small">Pre-generated content · No live generation<br/>Your choices are saved in this browser.</p><a class="e-subtle-link" href="/">Earlier demo: El último vagón →</a></section>
      <section v-else class="e-intro"><p class="e-kicker">One adventure. Your choices.</p><h1>What would you<br/>like to feel?</h1><p class="e-lead">Bring your mood, your curiosity, or just a little time. We’ll create a mystery for the moment you’re in.</p><p class="e-format">Read at your pace. Make three choices against the clock. Keep the story you lived.</p><button class="e-primary" :disabled="working||!!pending||!available" @click="ui.newAdventure">Begin the conversation <span aria-hidden="true">↗</span></button><p v-if="!available" class="e-small">New adventures are temporarily unavailable. Your previous stories remain saved.</p><p class="e-small">About 10–12 minutes of reading · Created with Meta</p><a class="e-subtle-link" href="/">Play El último vagón, the current demo →</a></section>
    </main>
    <main v-else-if="recoveryHome" class="e-preparing"><p class="e-kicker">Your place is saved</p><h1>A new moment, when you’re ready.</h1><p>Your previous preparation did not finish. Its conversation is saved; no new attempt has started.</p><p class="e-small">Saved reference: {{flow.id.slice(0,8)}}.</p><button class="e-primary" :disabled="working||!!pending||!available" @click="newAdventure">Begin a new conversation ↗</button><button class="e-link" @click="ui.inspectPreparation">View saved preparation</button><button class="e-link" @click="openLibrary">Your saved stories</button></main>
    <main v-else-if="chatMode" class="e-chat-layout">
      <aside class="e-chat-aside"><p class="e-kicker">Before the story</p><h1>A little about<br/> this moment.</h1><p>There is no right mood to bring. Tell us what you want to experience and what you’d rather leave out.</p><div class="e-aside-rule"></div><p class="e-small">A few questions. A proposal you can change. Then a story with one path that becomes yours.</p></aside>
      <section class="e-chat" aria-label="Create your adventure">
        <p class="e-small">Your chat is saved so you can return and we can investigate problems. Please avoid private details.</p>
        <div ref="chatLog" class="e-chat-log" role="log" aria-live="polite"><div v-for="(message,index) in flow.messages" :key="index" class="e-message" :class="message.role==='user'?'e-message-user':'e-message-assistant'"><span class="e-message-label">{{message.role==='user'?'You':'SEALED'}}</span><p>{{message.role==='assistant'?emotionalIntakeText(message.kind,message.content):message.content}}</p></div><div v-if="flow.status==='chatting'" class="e-message e-message-assistant e-thinking" role="status">Thinking about your story<span aria-hidden="true">…</span></div></div>
        <div v-if="flow.error" class="e-inline-note" role="status">We could not use that reply. You can clarify your preferences below; your conversation is saved. Reference: {{flow.id.slice(0,8)}}.</div>
        <section v-if="flow.status==='proposal'&&!editing" class="e-proposal" aria-label="Your story preferences"><p class="e-kicker">Does this feel right?</p><p>{{emotionalProposalSummary(flow.profile.experience)}}</p><div class="e-tags"><span>{{flow.profile.intensity==='unspecified'?'Intensity left open':flow.profile.intensity+' tension'}}</span><span>{{flow.profile.direction==='accompany'?'Stay with this feeling':flow.profile.direction==='shift'?'A change of atmosphere':'Atmosphere left open'}}</span></div><p class="e-boundaries">{{flow.profile.exclusions.length?'Leave out: '+flow.profile.exclusions.map(boundaryLabel).join(', '):'No extra boundaries specified.'}}</p><p class="e-small">Allow about 2–3 minutes to prepare a new adventure. Your conversation is saved.</p><button class="e-primary" :disabled="working||!!pending" @click="ui.confirm">Create my adventure <span aria-hidden="true">↗</span></button><button class="e-link e-edit" @click="editing=true">I’d like to change something</button></section>
        <form v-else class="e-composer" @submit.prevent="answer()"><div v-if="suggestions.length" class="e-suggestions"><button v-for="suggestion in suggestions" :key="suggestion" type="button" :disabled="working||!!pending" @click="answer(suggestion)">{{suggestion}}</button></div><label class="e-sr-only" for="e-answer">Your answer or preference</label><textarea id="e-answer" v-model="input" rows="2" maxlength="1000" :disabled="working||!!pending||flow.status==='chatting'" :placeholder="editing?'What would you like to change?':'Tell us as much or as little as you like…'"></textarea><div class="e-composer-actions"><button type="button" class="e-link" :disabled="working||!!pending||flow.status==='chatting'" @click="answer('I would rather leave that unspecified. Please continue with what I have already said.')">Skip this</button><button type="submit" class="e-send" :disabled="!input.trim()||working||!!pending||flow.status==='chatting'" aria-label="Send answer">Send ↗</button></div></form>
      </section>
    </main>
    <main v-else-if="flow.status==='queued'||flow.status==='generating'" class="e-preparing e-generation"><p class="e-kicker">An adventure taking shape</p><h1>{{stages[stage]!.title}}</h1><p role="status">{{stages[stage]!.description}}</p><ol class="e-preparation-stages" aria-label="Story preparation"><li v-for="(step,index) in stages" :key="step.title" :class="{'e-stage-done':index<stage,'e-stage-active':index===stage}" :aria-current="index===stage?'step':undefined"><span class="e-stage-symbol" aria-hidden="true">{{index<stage?'✓':index===stage?'●':'○'}}</span><span>{{step.title}}</span><span class="e-stage-track" aria-hidden="true"><span :style="{transform:'scaleX('+(index<stage?1:index>stage?0:stage===1?Math.min(.98,(flow.progress?.done??0)/21):.35)+')'}"></span></span></li></ol><p class="e-small">Allow about 2–3 minutes. You can leave this page and return.<br/>Nothing starts until you open your story.</p></main>
    <main v-else-if="flow.status==='failed'" class="e-preparing"><p class="e-kicker">This envelope stays closed</p><h1>The story wasn’t ready.</h1><p>We couldn’t prepare an adventure that passed the checks. Your conversation is saved, and no journey has started.</p><p class="e-small">If you report a problem, include reference {{flow.id.slice(0,8)}}.</p><button class="e-primary" :disabled="working||!!pending" @click="ui.newAdventure">Begin a different adventure ↗</button><a class="e-subtle-link" href="/">Return to the current demo →</a></main>
    <main v-else-if="finishedHome" class="e-preparing"><p class="e-kicker">One story to keep</p><h1>Your adventure is saved.</h1>
      <template v-if="props.prepared"><p>Return to your saved playthrough, or replay this same pre-generated Meta story. Your previous choices stay made.</p><button class="e-primary" @click="readingFinished=true">Return to my story →</button><button class="e-link" :disabled="working||!!pending||!available" @click="newAdventure">Replay this demo ↗</button></template>
      <template v-else><p>Return to your story, or begin a new conversation for a different adventure. Your previous choices stay made.</p><button class="e-primary" :disabled="working||!!pending||!available" @click="newAdventure">Begin a new adventure ↗</button><button class="e-link" @click="readingFinished=true">Return to my story →</button></template>
    </main>
    <main v-else-if="adventure" class="e-reader" :class="{'e-reader-sealed':flow.status==='ready'}">
      <div class="e-scene-art" :style="{'--scene-position':(['25% 45%','50% 50%','75% 50%','50% 60%'][chapter-1]),'--scene-zoom':String([1,1.08,1.15,1.04][chapter-1])}"><EmotionalIllustration v-if="adventure.art.some(a=>a.id==='scene')" :src="art('scene')" :alt="adventure.art.find(a=>a.id==='scene')?.alt"/><div class="e-art-shade"></div><div class="e-art-caption"><span>{{adventure.title}}</span><p>One story. One continuity.</p></div><div v-if="cast.length" class="e-cast" aria-label="People in this story"><span class="e-cast-label">Cast</span><div v-for="person in cast" :key="person.id"><EmotionalIllustration :src="art(person.id)" :alt="person.alt" :name="person.alt.replace('Portrait of ','')" compact/><span>{{person.alt.replace('Portrait of ','')}}</span></div><div class="e-player-cast"><span class="e-player-portrait" aria-hidden="true">{{initials(playerName)}}</span><span>You · {{playerName}}</span></div></div><button v-if="cast.length" class="e-cast-toggle" @click="people?.showModal()">Meet the cast</button></div>
      <section class="e-reading" :aria-busy="working">
        <template v-if="flow.status==='ready'"><p v-if="props.prepared" class="e-demo-disclosure">Pre-generated with Meta and reviewed before this demo. Each playthrough uses the same sealed story; the decisions are yours.</p><p class="e-kicker">Your envelope is sealed</p><h1>{{adventure.title}}</h1><p class="e-lead">{{adventure.goal}}</p><p class="e-format">Read each scene at your pace. Only the three decisions are timed: review the options, then start the 12 seconds when you’re ready. Silence has its own consequence.</p><p class="e-small">{{props.prepared?'The story and its possibilities were fixed before this demo.':'Your story and its possibilities are fixed now.'}} You can return after a break; choices already made stay made.</p><div class="e-sealed-stamp"><WaxSeal :size="64"/><div><strong>Sealed before you play</strong><code>{{initialSeal?.slice(0,16)}}…</code></div></div><p v-if="!commitmentStored" class="e-small">This browser could not retain the initial seal. Keep a copy before you begin: <code style="overflow-wrap:anywhere">{{initialSeal}}</code></p><button class="e-primary" :disabled="working||!!pending||sealMismatch" @click="ui.act('start')">Enter my story <span aria-hidden="true">↗</span></button></template>
        <template v-else-if="urgent&&decision"><CountdownBar :key="adventure.deadline??'opening'" :duration-ms="decision.durationMs" :remaining-ms="remaining" :ready="adventure.phase==='deciding'"/><div class="e-decision-heading"><p class="e-kicker">A moment that matters</p></div><h1 ref="question" class="e-decision-prompt" tabindex="-1">{{decision.prompt}}</h1><p class="e-small">{{adventure.phase!=='deciding'?'Opening this moment…':remaining<=0?'The moment has passed. Recovering what happened…':'There is no undo. Not choosing also lets the story continue.'}}</p><div class="e-choices"><button v-for="option in decision.options" :key="option.id" :aria-pressed="pending?.kind==='choose'&&pending.choice===option.id" :disabled="working||!!pending||adventure.phase!=='deciding'||remaining<=0" @click="ui.act('choose',option.id)"><span class="e-choice-letter" aria-hidden="true">{{option.id}}</span><span>{{option.label}}</span><span aria-hidden="true">↗</span></button></div><p class="e-small e-inaction">{{decision.inaction}}</p></template>
        <template v-else-if="reviewing&&decision"><div class="e-countdown-placeholder" aria-hidden="true"></div><div class="e-decision-heading"><p class="e-kicker">Before the clock starts</p></div><h1 ref="question" class="e-decision-prompt" tabindex="-1">{{decision.prompt}}</h1><p class="e-small">Read your options. Start the 12 seconds when you’re ready.</p><ol class="e-review-options"><li v-for="option in decision.options" :key="option.id"><strong>{{option.id}}</strong><span>{{option.label}}<small v-if="option.cost" class="e-option-cost">{{option.cost}}</small></span></li></ol><p class="e-small e-inaction">{{decision.inaction}}</p><div class="e-review-actions"><button class="e-primary" :disabled="working||!!pending||!!memoryId" @click="begin">Start decision · 12s <span aria-hidden="true">↗</span></button><button class="e-link" @click="reviewing=false">Back to reading</button></div></template>
        <template v-else><div class="e-reading-meta"><div><span class="e-chapter">Chapter {{chapter}} of 4</span><span>{{flow.status==='finished'?'Your ending':'Read at your pace'}}</span></div><div class="e-reading-tools"><span>{{pageIndex+1}} / {{pages.length}}</span><button class="e-link" @click="history?.showModal()">Story so far</button></div></div><p v-if="notice" class="e-inline-note e-timeout-note" role="status">{{notice}}</p><h1 class="e-scene-title">{{adventure.scene.title}}</h1><p v-if="choiceHint" class="e-small e-inline-note e-choice-copy-note" role="note">{{choiceHint}}</p><div ref="passage" class="e-passage" tabindex="0" aria-label="Story text"><p v-for="(text,index) in pages[pageIndex]" :key="adventure.scene.id+':'+pageIndex+':'+index">{{typographicQuotes(text)}}</p></div><div class="e-page-meta"><span class="e-decision-dots" role="img" :aria-label="adventure.decisions.length+' of 3 choices made'"><span v-for="n in 3" :key="n" aria-hidden="true">{{n<=adventure.decisions.length?'●':'○'}}</span></span><span>{{adventure.decisions.length}} of 3 choices made</span></div><div class="e-reading-actions"><button class="e-back" :disabled="pageIndex===0" aria-label="Previous page" @click="ui.previousPage">←</button><button v-if="!lastPage" class="e-primary" @click="ui.nextPage">Keep reading <span aria-hidden="true">→</span></button><button v-else-if="decision" class="e-primary" :disabled="working||!!pending||!!memoryId" @click="reviewing=true">Review this decision <span aria-hidden="true">↗</span></button><button v-else-if="flow.status==='finished'" class="e-primary" @click="openEnvelope"><WaxSeal state="cracked" :size="28"/>Open my envelope <span aria-hidden="true">↗</span></button><button v-else class="e-primary" :disabled="working||!!pending||!!memoryId" @click="ui.act('continue')">Continue the story <span aria-hidden="true">→</span></button></div></template>
      </section>
    </main>
    <div ref="measure" class="e-passage e-measure" aria-hidden="true"></div>
    <dialog ref="people" class="e-dialog" aria-labelledby="e-people-title"><div class="e-dialog-header"><p class="e-kicker">People in this story</p><button class="e-link" @click="people?.close()">Close</button></div><h2 id="e-people-title">The cast.</h2><div class="e-people"><figure v-for="person in cast" :key="person.id"><EmotionalIllustration :src="art(person.id)" :alt="person.alt" :name="person.alt.replace('Portrait of ','')"/><figcaption>{{person.alt.replace('Portrait of ','')}}</figcaption></figure><figure><span class="e-player-portrait e-player-card" role="img" :aria-label="'Your character: '+playerName">{{initials(playerName)}}</span><figcaption>You · {{playerName}}</figcaption></figure></div></dialog>
    <dialog ref="envelope" class="e-dialog e-envelope-dialog" aria-labelledby="e-envelope-title"><section :key="revealCount" class="e-letter"><div class="e-dialog-header"><p class="e-kicker">The envelope, opened</p><button class="e-link" @click="envelope?.close()">Close</button></div><WaxSeal state="opened" :size="64"/><h2 id="e-envelope-title">The story you lived.</h2><section v-if="openedTruth" class="e-letter-truth e-new-truth"><h3>The detail you carried</h3><p class="e-small">{{typographicQuotes(openedTruth.anchor)}}</p><EnvelopeText :text="typographicQuotes(openedTruth.truth)" :animated="animatedText"/><p class="e-small">A piece of their past, sealed before your first choice.</p></section><h3>Your choices</h3><ol class="e-debrief"><li v-for="(line,index) in adventure?.ending?.explanation.slice(0,3)" :key="line"><span>{{adventure?.decisions[index]?.choice==='T'?'Time passed':'You chose'}} · {{index+1}}</span><p>{{typographicQuotes(line)}}</p></li></ol><section v-if="adventure?.ending?.closedChoices?.length" class="e-folded-section"><h3>The choices left closed</h3><p class="e-small">These are the options you left behind. Their stories stayed folded.</p><ul class="e-folded-leaves"><li v-for="option in adventure.ending.closedChoices" :key="option.decision+option.choice"><span>Choice {{option.decision.slice(1)}} · {{option.choice==='T'?'Silence':option.choice}}</span><s>{{option.label}}</s></li></ul></section><section class="e-letter-truth"><h3>{{explanationHeading}}</h3><p v-if="explanationChoice==='B'||explanationChoice==='T'" class="e-small">Revealed now, after your story ended. Your character did not know this when making their choices.</p><EnvelopeText :text="typographicQuotes(adventure?.ending?.explanation[3]??'')" :animated="animatedText"/></section><div class="e-verified" :class="{'e-verified-failed':sealVerified===false}" role="status"><strong>{{sealVerified===true?'✓ The seal matches.':sealVerified===false?'The seal could not be confirmed.':'Verifying the seal…'}}</strong><p>The saved bytes are checked against the commitment made before you played.</p><code>{{shortHash}}</code><button class="e-link" @click="copyHash">Copy full hash</button><details><summary>Show full hash</summary><code>{{fullHash}}</code></details><p v-if="copied">{{copied}}</p></div><p class="e-small">This journey remains yours to reread. Its choices stay as they happened. What it leaves with you is yours to decide.</p><div class="e-dialog-actions"><button class="e-primary" @click="envelope?.close();history?.showModal()">Reread my journey →</button><button class="e-link" :disabled="!reveal" @click="download">Download the sealed record</button><a v-if="memoryId" class="e-subtle-link" :href="appPath">Return to my current story →</a><button v-else class="e-link" :disabled="working||!!pending" @click="newAdventure()">{{props.prepared?'Replay this demo':'Create a different adventure'}}</button></div></section></dialog>
    <dialog ref="history" class="e-dialog e-history" aria-labelledby="e-history-title"><div class="e-dialog-header"><p class="e-kicker">Your own path</p><button class="e-link" @click="history?.close()">Close</button></div><h2 id="e-history-title">{{adventure?.title}}</h2><p class="e-small">{{adventure?.goal}}</p><details v-for="(chapter,index) in adventure?.history" :key="index"><summary>{{index+1}}. {{chapter.title}}</summary><p v-for="(text,i) in chapter.paragraphs" :key="i">{{typographicQuotes(text)}}</p></details><p class="e-small">Only the scenes you lived are shown here.</p></dialog>
    <dialog ref="library" class="e-dialog" aria-labelledby="e-library-title"><div class="e-dialog-header"><p class="e-kicker">Your memories</p><button class="e-link" @click="library?.close()">Close</button></div><h2 id="e-library-title">Stories you have lived.</h2><p class="e-small" aria-label="Build version">Version: {{release||'not available'}}</p><label class="e-animation-setting"><input v-model="animatedText" type="checkbox"/> Animate the envelope text</label><p class="e-small">Access is saved in this browser and renewed when you return. Clearing site data loses that access. You can download a finished story’s sealed record from its envelope.</p><p v-if="!memories.length">Your finished adventures will be kept here, ready to reread.</p><a v-for="memory in memories" :key="memory.id" class="e-memory" :href="appPath+'?memory='+memory.id"><span>{{memory.title}}</span><span aria-hidden="true">→</span></a><a v-if="memoryId" class="e-subtle-link" :href="appPath">Return to my current story →</a><button v-if="canCreate" class="e-primary" :disabled="working||!!pending||!available" @click="newAdventure">{{props.prepared?'Replay this demo':'New adventure'}} <span aria-hidden="true">↗</span></button><a class="e-subtle-link" href="/">Play El último vagón, the original demo →</a></dialog>
  </div>
</template>
